mapper.select:
SELECT hour1.dsp_slot_id AS dsp_slot_id, hour1.date AS date, SUM(hour1.show_pv) AS show_pv, SUM(hour1.click_pv) AS click_pv, SUM(hour1.req_pv) AS req_pv, SUM(hour1.discard) AS discard, SUM(hour1.ret_pv) AS ret_pv, SUM(hour1.spend) AS spend, SUM(hour1.income) AS income, SUM(hour1.discount_click_pv) AS discount_click_pv, SUM(hour1.discount_show_pv) AS discount_show_pv, SUM(hour1.dplsucc_pv) AS dplsucc_pv, SUM(hour1.complete_pv) AS complete_pv, SUM(hour1.install_pv) AS install_pv, SUM(hour1.activate_pv) AS activate_pv,
MAX(hour1.dsp_slot_code) AS dspSlotCode, MAX(dsp.name) AS dspName, MAX(com.name) AS companyName, MAX(pro.name) AS productName, MAX(ssp.name_alise) AS sspName, MAX(app.name) AS appName, MAX(app.os_type) AS osType, MAX(media.media_company_short) AS mediaName
FROM data_dsp_slot_hour AS hour1 LEFT JOIN dsp_slot_info AS dsp ON dsp.id = hour1.dsp_slot_id LEFT JOIN dsp_company AS com ON com.id = dsp.company_id LEFT JOIN dsp_product AS pro ON pro.id = dsp.product_id
LEFT JOIN ssp_slot_info AS ssp ON ssp.id = hour1.ssp_slot_id LEFT JOIN ssp_app AS app ON app.id = ssp.app_id LEFT JOIN ssp_media AS media ON media.id = ssp.media_id
AND hour1.date = #{reqVO.date[0]}
AND hour1.date BETWEEN #{reqVO.date[0]} AND #{reqVO.date[1]}
AND dsp.company_id = #{reqVO.companyId}
AND dsp.os_type = #{reqVO.osType}
AND dsp.product_id IN
#{id}
AND hour1.dsp_slot_id IN
#{id}
AND hour1.dsp_slot_code IN
#{code}
AND hour1.dsp_slot_code = #{reqVO.dspSlotCode}
AND hour1.ssp_slot_id IN
#{id}
GROUP BY hour1.dsp_slot_id, hour1.date ORDER BY hour1.date DESC
